import {BUILD,SKILLS,LOCS,SLOTS,SLOTNAME,RARITY,fresh,stats,preset,encounter,step,reward,offline,forge,validSave,LEGENDARY_CODEX,codexState} from './engine.js';
import {drawScene} from './art.js';import {drawWorld,drawRegion,TERRITORIES} from './maps.js';import {icon,drawForge,drawMerchant} from './icons.js';
const $=id=>document.getElementById(id),KEY='ashencrown-v1';let s;try{let raw=localStorage.getItem(KEY);s=raw?JSON.parse(raw):fresh();if(!validSave(s))throw Error();}catch{s=fresh();}let e=null,view='world',race='dwarf',selected=s.equip.weapon,logs=[],selection=[],nextAt=0,lastStep=0,toastTimer,hitUntil=0;const away=offline(s);const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const matIcon={'铁屑':'iron','炉火晶':'fire','誓约残片':'soul'};const raceIcon={human:'sword',dwarf:'forge',elf:'soul',goblin:'merchant',ashen:'fire'};const conditions=[['always','可用即施放'],['low','生命低于60%'],['charge','敌人将重击'],['burn','目标已灼烧']];
function save(){s.lastSeen=Date.now();try{localStorage.setItem(KEY,JSON.stringify(s));$('saveStatus').textContent='已自动保存';}catch{$('saveStatus').textContent='请导出备份';}}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function modal(html){$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();} $('closeModal').onclick=()=>$('modal').close();$('modal').addEventListener('click',ev=>{if(ev.target===$('modal'))$('modal').close();});
function hud(){let st=stats(s);$('level').textContent='LV.'+s.level;$('xpText').textContent=s.xp+' / '+s.level*80;$('xpBar').style.width=s.xp/(s.level*80)*100+'%';$('stats').innerHTML=[['sword','攻击',st.atk],['shield','护甲',st.armor],['heart','生命',st.hp]].map(([i,n,v])=>`<div class="railStat">${icon(i)}<span>${n}</span><b>${v}</b></div>`).join('');$('gold').textContent=s.gold.toLocaleString();$('goldIcon').innerHTML=icon('gold');$('talentCount').textContent=Math.max(0,s.level-1-Object.values(s.talents).reduce((a,b)=>a+b,0));$('buildPicker').innerHTML=BUILD.map((b,i)=>`<button class="buildCard ${s.build===b.id?'active':''}" data-build="${b.id}" title="切换${b.name}构筑">${icon(['heavy','mark','guard'][i],b.id)}<strong>${b.name}</strong></button>`).join('');$('activityStatus').textContent=s.running?(e?.boss?'首领战进行中':'自动远征中'):'营地休整';$('dock').innerHTML=[['world','map','世界'],['battle','sword','远征'],['inventory','bag','装备'],['skills','mark','技能'],['forge','forge','锻炉'],['merchant','merchant','行商'],['journal','book','纪事'],['codex','firstforge','图鉴']].map(([v,i,n])=>`<button class="dockBtn ${view===v||(v==='world'&&view==='region')?'active':''}" data-view="${v}">${icon(i)}<span>${n}</span></button>`).join('');}
function heading(title,en,actions=''){$('viewTitle').textContent=title;$('viewEyebrow').textContent=en;$('viewActions').innerHTML=actions;}
function worldView(){heading('五族疆域','A WORLD DIVIDED');$('worldStatus').textContent='点击领地进入区域地图。矮人黑炉山脉现已开放。';return `<div class="viewport"><canvas class="mapCanvas" id="worldCanvas" width="960" height="540" aria-label="五族像素世界地图"></canvas><div class="mapOverlay">${TERRITORIES.map(t=>`<button class="territoryPin ${t.id==='dwarf'?'playable':''}" style="left:${t.x*100}%;top:${t.y*100}%" data-race="${t.id}" aria-label="进入${t.name}领地">${icon(raceIcon[t.id])}<span><b>${t.name}</b><small>${t.id==='dwarf'?'黑炉山脉 · 可探索':'领地地图 · 预览'}</small></span></button>`).join('')}</div><div class="mapCorner"><span>灰冠历 317 年</span><strong>破碎盟约之地</strong></div><div class="mapHint"><b>◆</b> 五个种族，一位主角。你的旅程始于黑炉。</div></div>`;}
function regionView(){let t=TERRITORIES.find(x=>x.id===race)||TERRITORIES[1];heading(t.name+'领地',t.subtitle||'THE BORDERLANDS','<button data-view="world">← 世界地图</button>');$('worldStatus').textContent=race==='dwarf'?'选择据点，继续寻找失踪的商队。':'领地美术预览，不包含可玩关卡。';return `<div class="viewport"><canvas class="mapCanvas" id="regionCanvas" width="960" height="540" aria-label="${t.name}区域地图"></canvas>${race==='dwarf'?`<div class="mapOverlay">${LOCS.map((l,i)=>`<button class="territoryPin node ${s.bossWins[i]?'playable':''}" style="left:${[23,50,78][i]}%;top:${[50,62,40][i]}%" data-dungeon="${i}"><span class="nodeIcon">${icon(['sword','forge','shield'][i])}</span><b>${l.name}</b><small>${s.bossWins[i]?'✓ 首领已击败':'推荐 Lv.'+[1,3,5][i]} · ${l.mat}</small></button>`).join('')}</div><div class="mapCorner"><span>矮人 · 黑炉氏族</span><strong>黑炉山脉</strong></div><div class="mapHint">◆ 点击据点进入远征 · 三条道路，三份失落的线索</div>`:`<div class="previewRibbon">领地预览 · 尚未开放</div><div class="previewCenter"><strong>${t.name}的故事仍在远方</strong><p>此版本只开放矮人篇，其他种族不会切换你的主角。</p><button class="primary" data-race="dwarf">前往黑炉山脉</button></div>`}</div>`;}
function battleView(){heading(LOCS[s.location].name,LOCS[s.location].en,'<button data-region="dwarf">← 区域地图</button>');$('worldStatus').textContent=LOCS[s.location].desc;return `<div class="viewport"><canvas class="sceneCanvas" id="scene" width="960" height="420" aria-label="像素战斗场景"></canvas><div class="battleBadge"><span class="liveDot"></span><span id="battleState"></span></div><div class="hpCards"><div class="hpCard"><div><b>布洛克</b><small id="heroHp"></small></div><div class="healthBar"><i id="heroHpBar"></i></div></div><div class="hpCard enemy"><div><b id="enemyName"></b><small id="enemyHp"></small></div><div class="healthBar"><i id="enemyHpBar"></i></div></div></div><div class="battleControls"><div class="battleMessage" id="combatMessage">${esc(logs[0]||'炉火照亮了前路。准备出发。')}</div><div class="row"><button class="battleLogBtn" data-log="1">战报</button><button id="bossBtn" class="secondary">挑战首领</button><button id="runBtn" class="primary">开始远征</button></div></div></div>`;}
function itemDetail(it){if(!it)return'<div class="emptyMessage">点击装备查看属性</div>';let on=s.equip[it.slot]===it.id;return `<span class="detailIcon">${icon(it.slot,it.set||'anvil',it.rarity)}</span><h3 class="r${it.rarity}text">${esc(it.name)}${it.bless?' +'+it.bless:''}</h3><span class="rarityText">${RARITY[it.rarity]} / ${SLOTNAME[it.slot]} / LV.${it.level}</span><div class="itemStats"><div><b>${it.atk+(it.bless||0)*2}</b><small>攻击</small></div><div><b>${it.armor}</b><small>护甲</small></div><div><b>${it.hp}</b><small>生命</small></div></div><p>${it.set?BUILD.find(b=>b.id===it.set).name+'套装':'独立装备'}</p>${it.divine?`<div class="divineTag"><strong>✧ ${it.divine.name}</strong><small>永久加成：攻击 +${it.divine.bonus.atk} · 护甲 +${it.divine.bonus.armor} · 生命 +${it.divine.bonus.hp}<br>已计入上方数值</small></div>`:''}${it.rarity===4?'<p class="r4text">王烬：附加目标生命1%伤害，上限为自身攻击60%。</p>':''}<div class="detailActions"><button class="primary" data-equip="${it.id}" ${on?'disabled':''}>${on?'已装备':'装备'}</button><button data-lock="${it.id}">${it.locked?'解锁':'锁定'}</button><button data-sell="${it.id}" ${on||it.locked?'disabled':''}>出售 ${10+it.rarity*8}◈</button></div>`;}
function inventoryView(){heading('旅人行囊','EQUIPMENT & RELICS',`<button data-sellall="1">出售未锁非套装</button>`);$('worldStatus').textContent='点击装备查看详情。金色角标为已装备，◆ 为锁定。';let st=stats(s);return `<div class="panelPage inventoryLayout"><div><div class="sectionLabel">当前装备</div><div class="equipmentDoll"><canvas id="doll" width="160" height="150"></canvas>${SLOTS.map(k=>{let it=s.inventory.find(x=>x.id===s.equip[k]);return `<button class="equipSlot" data-item="${it.id}" title="${esc(it.name)}">${icon(k,it.set||'anvil',it.rarity)}<small>${SLOTNAME[k]}</small></button>`;}).join('')}</div></div><div class="bagSection"><div class="bagHeader"><span>战利品</span><b>${s.inventory.length} / 100</b></div><div class="bagGrid">${s.inventory.map(it=>`<button class="itemCell r${it.rarity} ${selected===it.id?'selected':''}" data-item="${it.id}" title="${esc(it.name)} · ${RARITY[it.rarity]}">${icon(it.slot,it.set||'anvil',it.rarity)}${s.equip[it.slot]===it.id?'<span class="equippedDot">E</span>':''}${it.locked?'<span class="lockedDot">◆</span>':''}${it.divine?'<span class="divineDot" title="神赐·炉火眷顾">✧</span>':''}</button>`).join('')}</div></div><div class="itemDetail">${itemDetail(s.inventory.find(x=>x.id===selected))}</div><div class="setLine">${BUILD.map(b=>`${b.name} ${st.count[b.id]||0}/4`).join('　／　')}<br>${BUILD.filter(b=>(st.count[b.id]||0)>=2).map(b=>b.bonus).join('　')||'同套 2 / 4 件触发加成。'}</div></div>`;}
function skillsView(){heading('战技铭刻','RUNES & COMBAT ORDERS');$('worldStatus').textContent='点击技能图标更换。三个技能按从左到右的优先级施放。';return `<div class="panelPage"><div class="sectionLabel">已装备战技 · 由左至右执行</div><div class="skillLoadout">${s.skills.map((k,i)=>`<div class="skillSlot"><span class="priorityBadge">0${i+1} / CD ${SKILLS[k].cd}</span><button class="skillIconBtn" data-slot="${i}" title="更换${SKILLS[k].name}">${icon(k,s.build)}</button><h3>${SKILLS[k].name}</h3><p>${SKILLS[k].desc}</p><select data-condition="${i}" aria-label="${SKILLS[k].name}触发条件">${conditions.map(([v,n])=>`<option value="${v}" ${s.conditions[i]===v?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}</div><div class="sectionLabel">矮人战技图鉴</div><div class="skillPool">${Object.entries(SKILLS).map(([k,v])=>`<button data-skillinfo="${k}">${icon(k)}${v.name}</button>`).join('')}</div><p class="subtleText">冷却中自动普攻 · 无流派硬免疫 · 可自由混搭</p></div>`;}
function forgeView(){heading('黑炉锻坊','THE LAST EMBERS');$('worldStatus').textContent='自由融合：材料只影响概率，不指定部位、套装或成品。';return `<div class="viewport"><canvas class="workshopCanvas" id="forgeCanvas" width="960" height="320" aria-label="像素矮人锻造工坊"></canvas><div class="workshopBottom"><div class="fusionSlots">${Array.from({length:5},(_,i)=>`<button class="fusionSlot" data-remove="${i}" title="${selection[i]?selection[i]+' · 点击移除':'空材料槽'}">${selection[i]?icon(matIcon[selection[i]]):'+'}</button>`).join('')}</div><div class="materialRow">${Object.entries(s.materials).map(([k,n])=>`<button class="materialCard" data-material="${k}">${icon(matIcon[k])}<span>${k} ×${n}<small>${{'铁屑':'金属 · 武具倾向','炉火晶':'火焰 · 饰品倾向','誓约残片':'灵魂 · 饰品倾向'}[k]}</small></span></button>`).join('')}</div><div class="craftControls"><span class="fusionRandom">? 随机成品</span><button id="forgeBtn" class="primary">点燃熔炉 · 40◈</button><button id="blessBtn">武器强化 · 30◈</button></div><p class="subtleText">v0.3 装备材料融合试玩：当前只支持三种材料，随机产出四部位装备；暂不支持装备投入、药草或药剂。<br>非套装80% / 套装20%（暂定调试值）；材料配比影响部位与套装概率，均不保证。<br>沿用旧版品质：史诗15% + 每份材料4%，原型传说2%；不是正式新品质体系。<br>偶发神赐3%：成品基础攻击、护甲、生命 +10%（向上取整），永久保存，不额外扣费。<br>强化每次 +2 攻击，最多5次。满包时无法锻造。</p></div></div>`;}
function merchantView(){heading('尼克的行囊','THE GOBLIN TRADER');$('worldStatus').textContent='“盟约碎了，买卖还得做。” —— 哥布林行商尼克';return `<div class="viewport"><canvas class="workshopCanvas" id="merchantCanvas" width="960" height="320" aria-label="像素哥布林商人摊位"></canvas><div class="workshopBottom"><div class="marketCards"><div class="marketCard">${icon('bag')}<h3>旅途材料包</h3><p>三种材料各 2 份<br>本章库存 ${s.stock} / 3</p><button id="buyBtn" class="primary" ${s.stock<=0?'disabled':''}>购买 · 25◈</button></div><div class="marketCard">${icon('weapon','rune',3)}<h3>整理战利品</h3><p>出售未锁定的非套装装备<br>不会出售已装备物品</p><button data-sellall="1">批量出售</button></div></div><p class="subtleText">限量补给不会无限刷新。通过远征获取更多材料。</p></div></div>`;}
function journalView(){heading('诸境纪事','THE MISSING CARAVAN','<button data-log="1">战斗记录</button>');$('worldStatus').textContent='五族的旧盟约已经崩塌，商队是最后一条补给线。';return `<div class="panelPage"><div class="questCards">${LOCS.map((l,i)=>`<div class="questCard ${s.bossWins[i]?'done':''}">${icon(['sword','forge','shield'][i])}<h3>${l.name}</h3><p>${s.bossWins[i]?'✓ 线索已找到':'击败首领寻找线索'}</p></div>`).join('')}</div>${s.chronicle.map(t=>`<div class="chronicle">${esc(t)}</div>`).join('')}<p class="subtleText">已胜利 ${s.kills} 场 · 纪事为章节事件，非完整政治模拟</p></div>`;}
function codexView(){heading('传说遗物图鉴','RELICS OF THE OLD KINGS');$('worldStatus').textContent='v0.3 图鉴预览：初炉誓锤尚未进入掉落或融合池。';const entry=LEGENDARY_CODEX[0],state=codexState(s,entry.id);return `<div class="panelPage codexPage"><div class="codexGallery"><div class="sectionLabel">已确认的传说设计 · 01</div><button class="codexTile" data-codex="${entry.id}">${icon(entry.icon,'guard',4)}<span>${entry.name}</span><small>${state.status}</small></button><div class="codexEmpty">更多遗物，等待传闻揭晓。</div></div><article class="codexDetail"><span class="codexSigil">${icon(entry.icon,'guard',4)}</span><div class="eyebrow">DYNASTY · THE FIRST FORGE</div><h2>${entry.name}</h2><span class="codexBadge">${state.status} / 尚未实装</span><p class="relicLore">${entry.lore}</p><div class="relicAffix"><strong>固定词条 · ${entry.affix}</strong><p>${entry.effect}</p><small>${entry.tuning}</small></div><div class="codexMeta"><span>${entry.acquisition}</span><span>${entry.attributes}</span></div><p class="subtleText">此页展示已确认设计，不代表背包拥有或可掉落。旧版「王烬」原型装备继续保留，不计为初炉誓锤。其他传说武器尚未确认，本次不添加。</p></article></div>`;}
function render(){hud();$('view').innerHTML=({world:worldView,region:regionView,battle:battleView,inventory:inventoryView,skills:skillsView,forge:forgeView,merchant:merchantView,journal:journalView,codex:codexView}[view])();if(view==='inventory')portrait($('doll'));if(view==='world')drawWorld($('worldCanvas'),0);if(view==='region')drawRegion($('regionCanvas'),race,0);battleHud();}
function battleHud(){if(view!=='battle')return;let st=stats(s),hp=e?e.heroHp:st.hp;$('heroHp').textContent=Math.ceil(hp)+'/'+st.hp;$('heroHpBar').style.width=Math.min(100,hp/st.hp*100)+'%';$('enemyName').textContent=e?e.name:'未知敌人';$('enemyHp').textContent=e?Math.max(0,Math.ceil(e.hp))+'/'+e.max:'—';$('enemyHpBar').style.width=(e?Math.max(0,e.hp/e.max*100):100)+'%';$('battleState').textContent=s.running?(e?.boss?'首领战 · 回合 '+e.round:'自动远征 · 回合 '+(e?.round||0)):'营地休整';$('runBtn').textContent=s.running?'Ⅱ 暂停':'▶ 开始远征';let cd=Math.max(0,Math.ceil((s.bossReady[s.location]-Date.now())/1000));$('bossBtn').textContent=cd?'奖励冷却 '+cd+'s':'挑战首领';$('bossBtn').disabled=cd>0||!!(e?.boss&&!e.done);}
function resetFight(){e=null;nextAt=0;lastStep=Date.now();render();save();}function start(boss=false){s.running=true;e=encounter(s,boss);lastStep=Date.now();logs.unshift((boss?'首领现身：':'遭遇 ')+e.name);hud();battleHud();save();}function go(v){view=v;render();}
function showSkillChoice(slot){modal(`<h2>选择第 ${slot+1} 个战技</h2>${Object.entries(SKILLS).map(([k,v])=>`<button class="skillChoice" data-assign="${k}" data-index="${slot}" ${s.skills.some((x,i)=>x===k&&i!==slot)?'disabled':''}>${icon(k)}<span><strong>${v.name}</strong><small>${v.desc}</small></span></button>`).join('')}`);}
function showLog(){modal('<h2>战斗记录</h2><div class="logList">'+(logs.length?logs.map(t=>'<p>'+esc(t)+'</p>').join(''):'尚未开始远征。')+'</div>');}
document.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.view)go(b.dataset.view);if(b.dataset.race||b.dataset.region){race=b.dataset.race||b.dataset.region;go('region');}if(b.dataset.dungeon!==undefined){s.location=+b.dataset.dungeon;e=null;view='battle';render();save();}if(b.dataset.build){preset(s,b.dataset.build);selected=s.equip.weapon;resetFight();toast('已切换 '+BUILD.find(x=>x.id===s.build).name+'构筑');}if(b.dataset.item){selected=b.dataset.item;render();}if(b.dataset.equip){if($('modal').open)$('modal').close();let it=s.inventory.find(x=>x.id===b.dataset.equip);s.equip[it.slot]=it.id;s.build='custom';resetFight();toast('已装备 '+it.name);}if(b.dataset.lock){if($('modal').open)$('modal').close();let it=s.inventory.find(x=>x.id===b.dataset.lock);it.locked=!it.locked;save();render();}if(b.dataset.sell){if($('modal').open)$('modal').close();let it=s.inventory.find(x=>x.id===b.dataset.sell);if(it&&!it.locked&&s.equip[it.slot]!==it.id){s.gold+=10+it.rarity*8;s.inventory=s.inventory.filter(x=>x.id!==it.id);selected=s.equip.weapon;render();save();}}if(b.dataset.sellall){let ids=Object.values(s.equip),sold=s.inventory.filter(x=>!x.set&&!x.locked&&!ids.includes(x.id));s.gold+=sold.reduce((a,x)=>a+10+x.rarity*8,0);s.inventory=s.inventory.filter(x=>!sold.includes(x));if(!s.inventory.find(x=>x.id===selected))selected=s.equip.weapon;render();save();toast('已出售 '+sold.length+' 件非套装装备');}if(b.dataset.slot!==undefined)showSkillChoice(+b.dataset.slot);if(b.dataset.assign){s.skills[+b.dataset.index]=b.dataset.assign;s.build='custom';$('modal').close();resetFight();}if(b.dataset.skillinfo){let k=b.dataset.skillinfo;modal(`<span class="detailIcon">${icon(k)}</span><h2>${SKILLS[k].name}</h2><p>${SKILLS[k].desc}</p><p>冷却 ${SKILLS[k].cd} 回合。点击已装备槽位的图标可替换技能。</p>`);}if(b.dataset.material){let k=b.dataset.material;if(selection.length>=5)return toast('最多放入5份材料');if(selection.filter(x=>x===k).length>=s.materials[k])return toast('该材料不足');selection.push(k);render();}if(b.dataset.remove!==undefined&&selection[+b.dataset.remove]){selection.splice(+b.dataset.remove,1);render();}if(b.id==='forgeBtn'){let it=forge(s,selection);if(!it)return toast('需要材料、40金币和空余行囊');selection=[];selected=it.id;render();save();modal(`<div class="eyebrow">FORGED IN EMBERS</div><h2>${it.divine?'神赐降临 · 炉火眷顾':'锻造完成'}</h2>${it.divine?'<div class="divineBanner">炉火回应了你的祈愿。成品基础属性获得永久提升。</div>':''}<div class="itemDetail">${itemDetail(it)}</div>`);}if(b.id==='blessBtn'){let it=s.inventory.find(x=>x.id===s.equip.weapon);if(it.bless>=5)return toast('武器强化已达上限');if(s.gold<30)return toast('金币不足');s.gold-=30;it.bless++;hud();save();toast('强化成功，武器攻击 +2');}if(b.id==='buyBtn'){if(s.gold<25)return toast('金币不足');if(!s.stock)return;s.gold-=25;s.stock--;for(let k in s.materials)s.materials[k]+=2;render();save();toast('获得每种材料各2份');}if(b.id==='runBtn'){if(s.running){s.running=false;hud();battleHud();save();}else if(e&&!e.done){s.running=true;lastStep=Date.now();hud();battleHud();save();}else start();}if(b.id==='bossBtn'&&Date.now()>=s.bossReady[s.location])start(true);if(b.dataset.log)showLog();if(b.dataset.codex){toast('设计预览：尚未实装掉落与属性');}if(b.dataset.talent){let used=Object.values(s.talents).reduce((a,n)=>a+n,0);if(used>=s.level-1)return toast('升级后获得天赋点');s.talents[b.dataset.talent]++;save();hud();showTalents();}if(b.id==='beginBtn'){$('modal').close();race='dwarf';go('region');}});
document.addEventListener('change',ev=>{if(ev.target.dataset.condition!==undefined){s.conditions[+ev.target.dataset.condition]=ev.target.value;save();}});
function showTalents(){let points=s.level-1-Object.values(s.talents).reduce((a,b)=>a+b,0);modal(`<div class="eyebrow">DWARVEN LEGACY</div><h2>黑炉血脉</h2><p>剩余 ${points} 点。每升一级获得1点，可免费重置。</p>`+[['power','锻锤之力','每点 +3 攻击','sword'],['heart','山脉之心','每点 +20 生命','heart'],['steel','钢铁之躯','每点 +3 护甲','shield']].map(([k,n,d,i])=>`<div class="modalChoice">${icon(i)}<div><h4>${n} · ${s.talents[k]}</h4><p>${d}</p></div><button data-talent="${k}" ${points<=0?'disabled':''}>提升</button></div>`).join('')+'<button id="resetTalentBtn">免费重置天赋</button>');$('resetTalentBtn').onclick=()=>{s.talents={power:0,heart:0,steel:0};resetFight();showTalents();toast('天赋点已全部返还');};} $('talentBtn').onclick=showTalents;$('homeBtn').onclick=()=>go('world');
$('helpBtn').onclick=()=>modal(`<div class="eyebrow">WELCOME, FORGEBEARER</div><h2>炉火未熄，旅途开始。</h2><p>点击世界地图上的矮人领地，再选择据点展开自动远征。</p><ol><li>三个构筑预设可直接试用，初始套装已经备好。</li><li>远征获得装备、经验和材料；挑战首领推进商队线索。</li><li>点击装备图标查看与穿戴，点击技能槽更换战技。</li><li>把材料放入五个锻造槽，打造新装备。</li></ol><p>一份存档固定一名矮人主角。其他种族领地当前仅为地图预览。没有硬性流派免疫。</p><p>自动远征开启后离线收益最多4小时。当前浏览器存档，可在设置中导出备份。</p><button class="primary" id="beginBtn">前往黑炉山脉</button>`);
$('settingsBtn').onclick=()=>{modal('<h2>旅途存档</h2><p>进度保存在当前浏览器，建议导出备份。没有云同步。</p><div class="row"><button id="exportBtn">导出存档</button><button id="importBtn">导入存档</button><button id="restartBtn" class="danger">重新开始</button></div><input id="importFile" type="file" accept="application/json" hidden>');$('exportBtn').onclick=()=>{save();let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));a.download='灰冠诸境-布洛克.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async ev=>{try{let v=JSON.parse(await ev.target.files[0].text());if(!validSave(v))throw Error();if(!confirm('导入将覆盖当前进度，确定继续？'))return;s=v;s.running=false;e=null;selected=s.equip.weapon;save();render();$('modal').close();toast('存档已导入');}catch{toast('存档格式无效，未覆盖当前进度');}};$('restartBtn').onclick=()=>{if(confirm('确定清除当前旅程并重新开始？此操作不能撤销，建议先导出。')){s=fresh();e=null;logs=[];selection=[];selected=s.equip.weapon;view='world';save();render();$('modal').close();toast('新的旅程已经开始');}};};
function tick(now){if(document.hidden)return;if(s.running&&now-lastStep>1100){lastStep=now;if(!e||e.done){if(now>=nextAt)start(false);}else{logs.unshift(...step(s,e).reverse());logs=logs.slice(0,30);hitUntil=now+280;if(e.done){if(e.win){let it=reward(s,e);logs.unshift(e.boss?'首领已击败，获得新的商队线索。':'战斗胜利 · 获得'+LOCS[s.location].mat);if(it)logs.unshift('获得 '+RARITY[it.rarity]+' '+it.name);if(e.boss){s.running=false;toast('首领战胜利！新线索已记录。');}}else{s.running=false;logs.unshift('已撤回营地，提升装备或等级后重试。');toast('战斗失败，没有首领奖励冷却');}nextAt=now+1800;hud();if(['inventory','journal'].includes(view))render();save();}if($('combatMessage'))$('combatMessage').textContent=logs[0];battleHud();}}}
function portrait(canvas){if(!canvas)return;let pc=canvas.getContext('2d');pc.clearRect(0,0,160,150);pc.imageSmoothingEnabled=false;let rect=(x,y,w,h,c)=>{pc.fillStyle=c;pc.fillRect(x,y,w,h)};rect(38,128,88,7,'#10271b');rect(53,80,53,40,'#536f4f');rect(48,86,15,24,'#85956b');rect(100,86,16,24,'#85956b');rect(62,42,37,32,'#cbb27c');rect(55,37,50,12,'#718263');rect(61,28,37,12,'#9ea279');rect(77,23,9,27,'#d0b574');rect(60,59,43,12,'#ddc597');rect(64,68,35,31,'#bfab81');rect(70,94,24,9,'#bfab81');rect(67,53,7,5,'#203a2c');rect(88,53,7,5,'#203a2c');rect(75,62,13,7,'#a07a4b');rect(58,109,17,17,'#3f5940');rect(89,109,17,17,'#3f5940');rect(120,60,6,66,'#917146');rect(108,53,28,18,'#839477');rect(110,53,24,4,'#b4bf91');rect(47,101,13,8,'#cbb27c');}
let frame=0;function animate(t){if(t-frame>70){frame=t;if(view==='battle')drawScene($('scene'),{location:s.location,fighting:s.running&&!!e&&!e.done,boss:!!e?.boss,heroHp:e?e.heroHp/stats(s).hp:1,enemyHp:e?e.hp/e.max:1,time:t,hit:Date.now()<hitUntil});if(view==='forge')drawForge($('forgeCanvas'),t);if(view==='merchant')drawMerchant($('merchantCanvas'),t);}requestAnimationFrame(animate);}render();portrait($('portrait'));requestAnimationFrame(animate);setInterval(()=>{tick(Date.now());battleHud();},250);setInterval(()=>{if(!document.hidden)save();},10000);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{let r=offline(s);if(r){e=null;toast(`离线驻扎：+${r.gold}金币，+${r.xp}经验`);render();save();}}});if(away)toast(`离线${away.minutes}分钟：+${away.gold}金币，+${away.xp}经验，+${away.mat}材料`);save();
